challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The HSS (pyhss) is unresponsive to Diameter Cx requests, causing a complete failure of IMS registration and authentication.",
      "primary_suspect_nf": "pyhss",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "from:'icscf', to:'pyhss'",
          "expected_if_hypothesis_holds": "High RTT or packet loss, indicating unresponsiveness.",
          "falsifying_observation": "Normal RTT and no packet loss. This would suggest the network path is healthy and the HSS is responsive at the network layer.",
          "conflates_with": [
            "The icscf container has a network issue.",
            "The network path between icscf and pyhss is degraded."
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from:'scscf', to:'pyhss'",
          "expected_if_hypothesis_holds": "High RTT or packet loss, confirming pyhss unresponsiveness from a different source.",
          "falsifying_observation": "Normal RTT and no packet loss. If the first probe showed issues, this would isolate the problem to the icscf or its specific path, not pyhss.",
          "conflates_with": []
        },
        {
          "tool": "check_process_listeners",
          "args_hint": "container:'pyhss'",
          "expected_if_hypothesis_holds": "A process is listening on the Diameter port 3868/tcp, indicating the process is running but may be hung or otherwise unresponsive.",
          "falsifying_observation": "No process is listening on port 3868/tcp. This points to a different failure mode, such as the process having failed to start.",
          "conflates_with": []
        }
      ],
      "notes": "This plan tests the 'unresponsive' claim from h1. It uses a paired set of 'measure_rtt' probes to isolate unresponsiveness to the pyhss container versus the network path or source container. It also checks for a more fundamental failure (a non-listening process) as a falsifying condition."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "A DNS failure is preventing IMS components from resolving the hostname for the HSS, leading to the observed Diameter Cx timeouts and registration failures.",
      "primary_suspect_nf": "dns",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "from:'icscf', to:'dns'",
          "expected_if_hypothesis_holds": "High RTT or packet loss, indicating network-level connectivity issues to the DNS server.",
          "falsifying_observation": "Normal RTT and no packet loss, suggesting network connectivity to the DNS server is fine.",
          "conflates_with": [
            "The icscf container has a network issue.",
            "The network path between icscf and dns is degraded."
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from:'scscf', to:'dns'",
          "expected_if_hypothesis_holds": "High RTT or packet loss, confirming issues reaching the DNS server from multiple clients.",
          "falsifying_observation": "Normal RTT and no packet loss. If the first probe showed issues, this would point away from a general DNS NF failure.",
          "conflates_with": []
        },
        {
          "tool": "check_process_listeners",
          "args_hint": "container:'dns'",
          "expected_if_hypothesis_holds": "No process is listening on port 53/udp or 53/tcp, indicating the DNS server process itself is down.",
          "falsifying_observation": "A process is listening on port 53. This would suggest the DNS server process is running, and the issue might be in its configuration or upstream, rather than a process failure.",
          "conflates_with": []
        }
      ],
      "notes": "This plan attempts to falsify the DNS failure hypothesis by checking network reachability to the DNS container from two different IMS components and verifying that the DNS process is listening on its standard port."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "The UPF has experienced a data plane failure, leading to a collapse in media traffic.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "read upf.activity_during_calls",
          "expected_if_hypothesis_holds": "The value of upf.activity_during_calls is near zero, indicating a collapse in media traffic despite active calls.",
          "falsifying_observation": "The value of upf.activity_during_calls is within its typical healthy range (e.g., > 0.3), indicating media traffic is flowing as expected for the number of active calls.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "read ims.rtpengine.errors_per_second",
          "expected_if_hypothesis_holds": "The value of ims.rtpengine.errors_per_second is zero. This would be consistent with a data plane failure located at the UPF, external to RTPEngine.",
          "falsifying_observation": "A spike in ims.rtpengine.errors_per_second. This would suggest the problem lies with or at RTPEngine, not (or not only) the UPF.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "window_seconds=120, read ims.rtpengine.loss_ratio",
          "expected_if_hypothesis_holds": "A spike in the reported loss ratio, consistent with packets being dropped in the data plane at the UPF.",
          "falsifying_observation": "The loss ratio is within its normal range (0.0-0.1). This observation would contradict the hypothesis of a data plane failure causing traffic loss.",
          "conflates_with": []
        }
      ],
      "notes": "This plan uses KB-curated probes to test the data plane failure hypothesis at the UPF. It checks for the expected collapse in activity, and uses metrics from the adjacent RTPEngine to disambiguate a UPF-specific failure from an issue within RTPEngine itself. Probes are based on KB candidates for h3."
    }
  ]
}
